using Commerce;

namespace Commerce.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup() => _cart = new ShoppingCart();

    // ───── AddItem ─────

    [TestMethod]
    public void AddItem_SingleItem_IncludedInTotal()
    {
        _cart.AddItem("SKU-1", 9.99m, 1);
        Assert.AreEqual(9.99m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleQuantity_MultipliesPrice()
    {
        _cart.AddItem("SKU-1", 5.00m, 3);
        Assert.AreEqual(15.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleItems_SumsAll()
    {
        _cart.AddItem("A", 10.00m, 1);
        _cart.AddItem("B", 20.00m, 2);
        Assert.AreEqual(50.00m, _cart.GetTotal());
    }

    // ───── RemoveItem ─────

    [TestMethod]
    public void RemoveItem_ExistingItem_ReturnsTrueAndRemovesFromTotal()
    {
        _cart.AddItem("A", 10.00m, 1);
        _cart.AddItem("B", 5.00m, 2);

        var result = _cart.RemoveItem("A");

        Assert.IsTrue(result);
        Assert.AreEqual(10.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void RemoveItem_NonExistentItem_ReturnsFalse()
    {
        _cart.AddItem("A", 10.00m, 1);
        Assert.IsFalse(_cart.RemoveItem("MISSING"));
    }

    [TestMethod]
    public void RemoveItem_EmptyCart_ReturnsFalse()
    {
        Assert.IsFalse(_cart.RemoveItem("A"));
    }

    // ───── GetTotal ─────

    [TestMethod]
    public void GetTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.GetTotal());
    }

    [TestMethod]
    public void GetTotal_AfterRemovingAllItems_ReturnsZero()
    {
        _cart.AddItem("A", 7.50m, 2);
        _cart.RemoveItem("A");
        Assert.AreEqual(0m, _cart.GetTotal());
    }

    // ───── ApplyPromoCode ─────

    [TestMethod]
    public void ApplyPromoCode_ValidCode_ReturnsTrueAndAppliesDiscount()
    {
        _cart.AddItem("A", 100.00m, 1);
        var result = _cart.ApplyPromoCode("SAVE10");

        Assert.IsTrue(result);
        Assert.AreEqual(90.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_CaseInsensitive()
    {
        _cart.AddItem("A", 100.00m, 1);
        _cart.ApplyPromoCode("save20");
        Assert.AreEqual(80.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_InvalidCode_ReturnsFalseAndNoDiscount()
    {
        _cart.AddItem("A", 100.00m, 1);
        var result = _cart.ApplyPromoCode("BOGUS");

        Assert.IsFalse(result);
        Assert.AreEqual(100.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_HalfOff_Applies50PercentDiscount()
    {
        _cart.AddItem("A", 60.00m, 2);
        _cart.ApplyPromoCode("HALF");
        Assert.AreEqual(60.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_OnEmptyCart_TotalRemainsZero()
    {
        _cart.ApplyPromoCode("SAVE10");
        Assert.AreEqual(0m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_DiscountAppliesToItemsAddedAfter()
    {
        _cart.ApplyPromoCode("SAVE20");
        _cart.AddItem("A", 50.00m, 1);
        Assert.AreEqual(40.00m, _cart.GetTotal());
    }
}

